// Anonymous per-install device identifier. Generated once on first
// launch, persisted in AsyncStorage, and sent as `X-Device-Id` on every
// request to the abfall-api backend.
//
// This is NOT a user identifier — it can be regenerated by clearing app
// data and changes if the user reinstalls. The server only uses it for
// rate limiting and per-device dedup (HMACed before storage), never to
// identify a human.

import AsyncStorage from "@react-native-async-storage/async-storage";

const KEY = "abfall_device_id";

/**
 * Manual UUID v4 generator — avoids pulling in a dep just for this. The
 * randomness here doesn't need to be cryptographically strong: the
 * server HMACs the value before storing, and we only need it to be
 * unique-with-overwhelming-probability across installs.
 */
function uuidv4(): string {
  return "xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx".replace(/[xy]/g, (c) => {
    const r = (Math.random() * 16) | 0;
    const v = c === "x" ? r : (r & 0x3) | 0x8;
    return v.toString(16);
  });
}

// Cache the resolved id so getDeviceId() is effectively sync after the
// first await — most callers don't want to AsyncStorage-roundtrip every
// time they make a request.
let cached: string | null = null;
let inflight: Promise<string> | null = null;

export async function getDeviceId(): Promise<string> {
  if (cached) return cached;
  if (inflight) return inflight;

  inflight = (async () => {
    const existing = await AsyncStorage.getItem(KEY);
    if (existing && existing.length >= 8) {
      cached = existing;
      return existing;
    }
    const fresh = uuidv4();
    await AsyncStorage.setItem(KEY, fresh);
    cached = fresh;
    return fresh;
  })();

  try {
    return await inflight;
  } finally {
    inflight = null;
  }
}

/**
 * Forget the cached id and remove it from storage. Called from the
 * Profile "Reset everything" action so a fresh-state user really starts
 * over with a new anonymous identity.
 */
export async function resetDeviceId(): Promise<void> {
  cached = null;
  try {
    await AsyncStorage.removeItem(KEY);
  } catch {}
}
